static mut BODIES: [f64; 4] = [0.0; 4];

pub fn read_body(i: usize) -> f64 {
    // Nothing checks i < 4: an index past the end is an out-of-bounds read.
    unsafe { *(&raw const BODIES).cast::<f64>().add(i) }
}

pub fn past_the_end() -> f64 {
    read_body(4)
}
